usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Users.Update(
		context.TODO(),
		"user_id",
		openai.AdminOrganizationUserUpdateParams{
			Role: param.NewOpt[string]("string"),
			RoleID: param.NewOpt[string]("string"),
			TechnicalLevel: param.NewOpt[string]("string"),
			DeveloperPersona: param.NewOpt[string]("string"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
